<?php require 'includes/functions.php';if(!logged())go('login.php');$title='Mon compte';$base='';$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION['user']['id']]);$orders=$s->fetchAll();require 'includes/header.php';?><section class="banner"><div class="container"><h1>MON COMPTE</h1><p>Bienvenue <?=e($_SESSION['user']['full_name'])?></p></div></section><section class="container section"><h2>Mes commandes</h2><?php if(!$orders):?><div class="empty">Aucune commande. <a href="shop.php">Découvrir la boutique</a></div><?php else:?><div class="tablewrap"><table><tr><th>Référence</th><th>Date</th><th>Total</th><th>Statut</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e(date('d/m/Y',strtotime($o['created_at'])))?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach?></table></div><?php endif?></section><?php require 'includes/footer.php';?>
